mapper.update:
UPDATE chat_rooms
SET name = #{roomName}
WHERE id = #{roomId}

mapper.select:
SELECT permission_type
FROM chat_room_permissions
WHERE room_id = #{roomId}
AND user_id = #{userId}

mapper.update:
UPDATE chat_participants
SET last_read_at = CURRENT_TIMESTAMP
WHERE room_id = #{roomId}
AND user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM chat_messages m
WHERE m.room_id = #{roomId}
AND m.sender_id != #{userId}  -- 본인이 보낸 메시지 제외
AND NOT EXISTS (
    SELECT 1 FROM chat_reads r 
    WHERE r.message_id = m.id 
    AND r.user_id = #{userId}
)

SELECT * FROM chat_message_files 
WHERE message_id = #{messageId}
ORDER BY uploaded_at ASC

SELECT * FROM chat_message_files WHERE message_id IN
#{messageId}
ORDER BY message_id ASC, uploaded_at ASC

mapper.update:
UPDATE chat_participants
SET left_at = CURRENT_TIMESTAMP
WHERE room_id = #{roomId}
AND user_id = #{userId}

UPDATE chat_participants
SET joined_at = CURRENT_TIMESTAMP,
    left_at = null
WHERE room_id = #{roomId}
AND user_id = #{userId}

UPDATE chat_invitations
SET status = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE room_id = #{roomId}
AND invitee_id = #{inviteeId}

mapper.select:
SELECT m.*, u.name as sender_name
FROM chat_messages m
JOIN users u ON m.sender_id = u.id
WHERE m.room_id = #{roomId}
AND m.is_deleted = false

    AND (
        m.message LIKE CONCAT('%', #{keyword}, '%')
        OR u.name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND m.sent_at >= #{startDate}


    AND m.sent_at <= #{endDate}

ORDER BY m.sent_at DESC
LIMIT #{offset}, #{limit}

SELECT DISTINCT r.* FROM chat_rooms r LEFT JOIN chat_room_tags t ON r.id = t.room_id LEFT JOIN chat_participants p ON r.id = p.room_id LEFT JOIN users u ON p.user_id = u.id WHERE 1=1
AND ( r.name LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%') OR t.tag_name LIKE CONCAT('%', #{keyword}, '%') OR u.name LIKE CONCAT('%', #{keyword}, '%') )
AND r.type = #{type}
AND r.created_at >= #{startDate}
AND r.created_at <= #{endDate}
AND EXISTS ( SELECT 1 FROM chat_participants p2 WHERE p2.room_id = r.id AND p2.user_id = #{userId} )
ORDER BY
r.name r.created_at r.last_message_at (SELECT COUNT(*) FROM chat_participants WHERE room_id = r.id) r.last_message_at
ASC DESC
LIMIT #{offset}, #{limit}

mapper.delete:
DELETE FROM chat_room_shares
WHERE room_id = #{roomId}
AND shared_by = #{sharedBy}

mapper.update:
UPDATE chat_room_settings
SET setting_value = #{settingValue},
    updated_at = CURRENT_TIMESTAMP
WHERE room_id = #{roomId}
AND setting_key = #{settingKey}

mapper.select:
SELECT setting_key, setting_value
FROM chat_room_settings
WHERE room_id = #{roomId}

SELECT m.*, u.name as sender_name
FROM chat_messages m
JOIN users u ON m.sender_id = u.id
WHERE m.room_id = #{roomId}

    AND m.message_type = #{messageType}


    AND m.sender_id = #{senderId}


    AND m.sent_at >= #{startDate}


    AND m.sent_at <= #{endDate}


    AND EXISTS (
        SELECT 1 FROM chat_message_files f 
        WHERE f.message_id = m.id
    )


    AND m.is_pinned = #{isPinned}

ORDER BY m.sent_at DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE chat_participants
SET role = #{role},
    updated_at = CURRENT_TIMESTAMP
WHERE room_id = #{roomId}
AND user_id = #{userId}

mapper.select:
SELECT p.*, u.name as user_name
FROM chat_participants p
JOIN users u ON p.user_id = u.id
WHERE p.room_id = #{roomId}
AND p.role = #{role}

SELECT id, message_format, formatted_message
FROM chat_messages
WHERE room_id = #{roomId}
AND message_format IS NOT NULL
ORDER BY sent_at DESC
LIMIT #{limit}

SELECT m.*, u.name as sender_name
FROM chat_messages m
JOIN users u ON m.sender_id = u.id
WHERE m.room_id = #{roomId}
AND m.message_type = 'BOT'
AND m.bot_type = #{botType}
ORDER BY m.created_at DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO chat_reads (message_id, user_id, read_at)
SELECT m.id, #{userId}, CURRENT_TIMESTAMP
FROM chat_messages m
WHERE m.room_id = #{roomId}
AND m.sender_id != #{userId}  -- 본인이 보낸 메시지 제외
AND NOT EXISTS (
    SELECT 1 FROM chat_reads r 
    WHERE r.message_id = m.id 
    AND r.user_id = #{userId}
)
